B.aIQ=new A.ii('Bu kullan\u0131m ko\u015fullar\u0131, Koala by evlumba uygulamas\u0131n\u0131 ("Uygulama") kullan\u0131m\u0131n\u0131z\u0131 d\xfczenler. Uygulamay\u0131 kullanarak bu ko\u015fullar\u0131 kabul etmi\u015f say\u0131l\u0131rs\u0131n\u0131z.',null)
B.aIT=new A.ii("Son g\xfcncelleme: 18 Mart 2026",null)
B.aK8=new A.iG("Hizmet Tan\u0131m\u0131",null)
B.aIM=new A.ii("Koala, yapay zeka destekli bir mekan analiz uygulamas\u0131d\u0131r. Kullan\u0131c\u0131lar soru foto\u011fraf\u0131 \xe7ekerek ad\u0131m ad\u0131m \xe7\xf6z\xfcm alabilir. Uygulama 9 farkl\u0131 bran\u015fta AI destekli \xf6\u011fretim hizmeti sunar.",null)
B.aK4=new A.iG("Hesap ve Kay\u0131t",null)
B.aGA=new A.ep("Uygulamay\u0131 kullanmak i\xe7in Google veya telefon numaras\u0131 ile hesap olu\u015fturman\u0131z gerekir",null)
B.aGD=new A.ep("Hesap bilgilerinizin do\u011fru ve g\xfcncel olmas\u0131ndan siz sorumlusunuz",null)
B.aGm=new A.ep("Hesab\u0131n\u0131z\u0131n g\xfcvenli\u011finden siz sorumlusunuz",null)
B.aKd=new A.iG("Kredi Sistemi",null)
B.aGk=new A.ep("Her yeni kullan\u0131c\u0131ya 10 \xfccretsiz kredi verilir",null)
B.aGJ=new A.ep("Her mekan analizi 1 kredi harcar",null)
B.aGI=new A.ep("Ek kredi uygulama i\xe7i sat\u0131n alma ile edinilebilir",null)
B.aGH=new A.ep("Sat\u0131n al\u0131nan krediler iade edilemez",null)
B.aK5=new A.iG("Kabul Edilebilir Kullan\u0131m",null)
B.aIJ=new A.ii("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
B.aGG=new A.ep("Uygulamay\u0131 k\xf6t\xfcye kullanmak veya ba\u015fkalar\u0131n\u0131n kullan\u0131m\u0131n\u0131 engellemek",null)
B.aGz=new A.ep("Otomatik botlar veya scraper kullanmak",null)
B.aGC=new A.ep("Uygulamay\u0131 s\u0131nav s\u0131ras\u0131nda kopya \xe7ekmek i\xe7in kullanmak",null)
