B.aK6=new A.iG("Fikri M\xfclkiyet",null)
B.aIO=new A.ii("Uygulama ve i\xe7eri\u011fi Evlumba Software'a aittir. AI taraf\u0131ndan \xfcretilen \xe7\xf6z\xfcmler e\u011fitim ama\xe7l\u0131d\u0131r ve do\u011frulu\u011fu garanti edilmez.",null)
B.aK2=new A.iG("Sorumluluk S\u0131n\u0131rlamas\u0131",null)
